(()=>{'use strict';
 const E=window.FortunePractice,$=id=>document.getElementById(id),names=['Golden crest','Ruby','Emerald','Sapphire'],bets=[100,200,500,1000,2500,5000,10000],key='cw_fortune_practice_v2';
 let balance=1000000,betIndex=3,hitRate=30,history=[],lastWin=0,busy=false,animations=[],sound=false,audio,artId=0;
 try{const s=JSON.parse(localStorage.getItem(key)||'null');if(s&&Number.isSafeInteger(s.balance)&&s.balance>=0&&s.balance<1e12&&Array.isArray(s.history)){balance=s.balance;history=s.history.filter(r=>Number.isSafeInteger(r.bet)&&r.bet>0&&Number.isSafeInteger(r.payout)&&r.payout>=0&&r.payout<=r.bet*375&&E.multipliers.includes(r.multiplier)).slice(0,50);if(Number.isInteger(s.betIndex)&&s.betIndex>=0&&s.betIndex<bets.length)betIndex=s.betIndex;if(Number.isInteger(s.hitRate)&&s.hitRate>=0&&s.hitRate<=100)hitRate=s.hitRate;lastWin=history[0]?.payout||0;}}catch{}
 const format=cents=>(cents/100).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
 function save(){try{localStorage.setItem(key,JSON.stringify({balance,betIndex,hitRate,history}));}catch{}}
 function art(s){const id='fg'+(++artId),color=['#ffd675','#ff345e','#50dd95','#59acff'][s],dark=['#8e4719','#890c3a','#146648','#152c7a'][s];
 const crest='<path d="M50 12 63 35 91 23 82 62 65 75 50 91 35 75 18 62 9 23 37 35Z"/><path d="M23 42 42 48 50 29 58 48 77 42 65 65 50 78 35 65Z" fill="#e8a445" stroke="#ffe8b2" stroke-width="2"/><path d="m50 43 12 14-12 13-12-13Z" fill="#bb2457"/><path d="M28 82Q50 70 72 82L77 91H23Z" fill="#ffda78"/>';
 const shapes=['', '<path d="M50 9 78 18 93 43 85 73 61 91 30 85 9 62 12 31Z"/><path d="m50 9-9 26-29-4 19 24-22 7 33 9-12 14 25-17 6 23 5-29 19 11-14-26 22-4-28-8 13-17-27 9Z" fill="#ff9ea8" opacity=".4"/><path d="m41 35 24 0 6 12-16 21-24-13Z" fill="#ff4975" stroke="#ffd3c6" stroke-width="2"/>', '<path d="m25 11 51 0 15 18 0 49-17 13H24L9 76V27Z"/><path d="m25 11 9 20h34l8-20M9 27l25 4v37L9 76M91 29l-23 2v37l23 10M24 91l10-23h34l6 23" fill="none" stroke="#aaffd3" stroke-width="3"/><path d="M34 31h34v37H34Z" fill="#39c78a" stroke="#e2ffbf" stroke-width="2"/>', '<path d="M50 8 92 78 78 92H23L8 78Z"/><path d="m50 8-9 49L8 78l42-2 28 16-14-35 28 21Z" fill="#9ce9ff" opacity=".65"/><path d="m50 31 14 26-14 19-9-19Z" fill="#6591f6" stroke="#e2ffff" stroke-width="2"/>'];
 return `<svg viewBox="0 0 100 100" aria-hidden="true"><defs><radialGradient id="${id}"><stop stop-color="#fff6cd"/><stop offset=".35" stop-color="${color}"/><stop offset="1" stop-color="${dark}"/></radialGradient></defs><g fill="url(#${id})" stroke="#ffdf8b" stroke-width="2.5">${s===0?crest:shapes[s]}</g><path d="M20 22h12m-6-6v12" stroke="#fff9de" stroke-width="2" opacity=".85"/></svg>`;
 }
 function cell(symbol,winner=false){return `<div class="symbol${winner?' winner':''}" role="img" aria-label="${names[symbol]}">${art(symbol)}</div>`;}
 function setBoard(board,winners=[]){$('reels').innerHTML=[0,1,2].map(col=>`<div class="reel"><div class="strip">${[0,1,2].map(row=>cell(board[row*3+col],winners.includes(row*3+col))).join('')}</div></div>`).join('');}
 function meters(){ $('balance').textContent=format(balance);$('last-win').textContent=format(lastWin);$('bet-value').textContent=format(bets[betIndex]);$('bet-down').disabled=busy||betIndex===0;$('bet-up').disabled=busy||betIndex===bets.length-1;}
 function renderHistory(){ $('history').innerHTML=history.length?history.map((r,i)=>`<div class="history-row"><span>#${history.length-i} · Bet ${format(r.bet)}</span><span>${r.multiplier}× multiplier</span><span>${r.payout?'+'+format(r.payout):'No win'}</span></div>`).join(''):'<p class="empty">Your practice spins will appear here.</p>';}
 function tone(frequency,duration=.12,delay=0,type='sine'){if(!sound||!audio||audio.state!=='running')return;const osc=audio.createOscillator(),gain=audio.createGain(),start=audio.currentTime+delay;osc.type=type;osc.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.055,start+.012);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);osc.connect(gain);gain.connect(audio.destination);osc.start(start);osc.stop(start+duration+.02);osc.onended=()=>{osc.disconnect();gain.disconnect();};}
 function lock(value){busy=value;$('spin').disabled=value;$('stop').disabled=!value;$('menu').disabled=value;$('reset').disabled=value;$('hit-rate').disabled=value;$('spin').classList.toggle('is-spinning',value);meters();}
 async function spin(){if(busy)return;const bet=bets[betIndex];if(balance<bet){$('status').textContent='Not enough practice credits. Open the menu to reset.';return;}
  let result;try{result=E.spin(bet,hitRate);}catch{$('status').textContent='Practice spin could not start. Please retry.';return;}
  lock(true);balance-=bet;lastWin=0;meters();$('win').hidden=true;$('paylines').innerHTML='';$('status').textContent='Spinning…';tone(180,.18,0,'triangle');
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let tick=0;const timer=setInterval(()=>{tick=(tick+1)%3;document.querySelectorAll('.multiplier').forEach((el,i)=>el.classList.toggle('active',i===tick));},110);
  try{
   setBoard(result.board);animations=[];
   const tasks=[...document.querySelectorAll('.reel')].map(async(reel,col)=>{const strip=reel.firstElementChild,tail=[result.board[col],result.board[3+col],result.board[6+col]],sequence=[...Array.from({length:14},()=>E.int(4)),...tail];strip.innerHTML=sequence.map(n=>cell(n)).join('');reel.classList.add('spinning');const height=reel.clientHeight/3;const animation=strip.animate([{transform:'translateY(0)'},{transform:`translateY(${-14*height}px)`}],{duration:reduced?70:850+col*210,easing:'cubic-bezier(.12,.55,.22,1)',fill:'forwards'});animations.push(animation);await animation.finished;strip.innerHTML=tail.map(n=>cell(n)).join('');animation.cancel();reel.classList.remove('spinning');tone(370+col*100,.1);});
   await Promise.all(tasks);
  }catch{ /* A cancelled animation still reveals and settles this one practice outcome. */ }
  finally{clearInterval(timer);animations=[];document.querySelectorAll('.multiplier').forEach((el,i)=>el.classList.toggle('active',E.multipliers[i]===result.multiplier));}
  balance+=result.payout;lastWin=result.payout;setBoard(result.board,result.wins.flatMap(w=>w.cells));
  const paths=['M0 50H300','M0 150H300','M0 250H300','M0 0 300 300','M0 300 300 0'];$('paylines').innerHTML=result.wins.map(w=>`<path d="${paths[w.index]}"/>`).join('');
  $('status').textContent=result.payout?`${result.wins.length} winning ${result.wins.length===1?'line':'lines'} · ${result.multiplier}× multiplier`:'No winning line. Your next practice spin is ready.';
  if(result.payout){$('win').textContent='+'+format(result.payout);$('win').hidden=false;[523,659,784,1047].forEach((f,i)=>tone(f,.3,i*.11));}else tone(170,.22);
  history.unshift({bet,payout:result.payout,multiplier:result.multiplier});history=history.slice(0,50);save();renderHistory();lock(false);resize();
 }
 $('spin').onclick=spin;$('stop').onclick=()=>{for(const animation of animations)if(animation.playState==='running')animation.finish();};
 $('bet-down').onclick=()=>{if(!busy&&betIndex>0){betIndex--;meters();save();}};$('bet-up').onclick=()=>{if(!busy&&betIndex<bets.length-1){betIndex++;meters();save();}};
 $('menu').onclick=()=>{renderHistory();$('settings').showModal();};document.querySelector('[data-close]').onclick=()=>$('settings').close();
 $('hit-rate').value=hitRate;$('hit-value').textContent=hitRate+'%';$('hit-rate').oninput=e=>{if(busy)return;hitRate=Number(e.target.value);$('hit-value').textContent=hitRate+'%';save();};
 $('reset').onclick=()=>{if(busy)return;balance=1000000;lastWin=0;history=[];save();meters();renderHistory();$('status').textContent='Practice credits reset.';$('win').hidden=true;$('paylines').innerHTML='';setBoard([1,2,3,2,0,1,3,1,2]);};
 $('sound').onclick=async()=>{sound=!sound;try{if(sound){const Context=window.AudioContext||window.webkitAudioContext;if(!Context)throw Error();audio||=new Context();await audio.resume();}}catch{sound=false;}$('sound').setAttribute('aria-pressed',String(sound));$('sound').setAttribute('aria-label',sound?'Mute sound':'Enable sound');if(sound)tone(660,.12);};
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&audio)audio.suspend().catch(()=>{});else if(sound&&audio)audio.resume().catch(()=>{});});
 function resize(){if(parent!==window)parent.postMessage({type:'cw-fortune-height',height:Math.max(600,Math.ceil(document.querySelector('.game').getBoundingClientRect().height))},'*');}
 new ResizeObserver(resize).observe(document.querySelector('.game'));window.addEventListener('pagehide',()=>{sound=false;audio?.close().catch(()=>{});});
 setBoard([1,2,3,2,0,1,3,1,2]);meters();renderHistory();resize();
})();
